function viewSchem(m){ window.__dmsActive=false; schemView(m,SHEETS,'DMS-1','Redrawn from the firmware pin use, eerw.asm, the 2001/2011 silks and the two functional drawings. No DMS-1 schematic or netlist is in this folder.'); }

/* ---------------- software ---------------- */
function lcsDiff(a, b){ const n=a.length, m=b.length, T=new Uint16Array((n+1)*(m+1));
  for (let i=n-1;i>=0;i--) for (let j=m-1;j>=0;j--) T[i*(m+1)+j] = a[i]===b[j]? T[(i+1)*(m+1)+j+1]+1 : Math.max(T[(i+1)*(m+1)+j], T[i*(m+1)+j+1]);
  const out=[]; let i=0, j=0; while (i<n && j<m){ if (a[i]===b[j]){ out.push([' ',a[i],i+1]); i++; j++; } else if (T[(i+1)*(m+1)+j]>=T[i*(m+1)+j+1]){ out.push(['-',a[i],i+1]); i++; } else { out.push(['+',b[j],j+1]); j++; } }
  while (i<n) out.push(['-',a[i],++i]); while (j<m){ out.push(['+',b[j],j+1]); j++; } return out; }
const fileText = (v, name) => { const f=FW.V[v].files.find(x=>x[0].toLowerCase()===name.toLowerCase()); return f? f[1].map(k=>FW.S[k]) : null; };
let diffSel={a:'v101', b:'v102'};
function viewSoft(m){ window.__dmsActive=true;
  m.innerHTML=`${card('main — the call running at the playhead (cycle offsets measured in this pass)',`<div id="ml"></div>`)}
   <div class="grid2">${card('Source at the program counter',`<div id="src" class="mono small" style="white-space:pre;overflow:auto;max-height:420px;line-height:1.35"></div><p class="small muted">Step the transport by “1 instruction cycle” to walk through the code.</p>`)}${card('Last instructions executed',`<div id="ring" class="mono small"></div>`)}</div>
   <div class="grid2">${card('RAM map at the playhead (symbols from the assembled source)',`<div id="ram" class="scroll" style="max-height:420px"></div>`)}<div>${card('Who the PIC talks to (sources1,5)',`<div id="sm"></div>`)}${card('EEPROM 93LC66B at the playhead',`<div id="ee"></div>`)}</div></div>
   ${card('LED decisions in sdimode (sdi42.asm)',`<div id="ld"></div>`)}
   ${card('Version differences — straight from the archive files',`<div id="df"></div>`)}`;
  const drawDiff=()=>{ const names=[...new Set(['main'].concat(FW.V.v102.files.slice(1).map(f=>f[0])))];
    const sel2=(id,cur)=>sel(id,[['v100','v100'],['v101','v101'],['v102','v102']],cur);
    const fname=(v,n)=> n==='main'? FW.V[v].files[0][0] : n;
    let html=`<div class="small" style="display:flex;gap:10px;flex-wrap:wrap;align-items:center">${sel2('da',diffSel.a)} → ${sel2('db',diffSel.b)}</div>`;
    names.forEach(n=>{ const A_=fileText(diffSel.a,fname(diffSel.a,n)), B_=fileText(diffSel.b,fname(diffSel.b,n)); if (!A_||!B_) return; const d=lcsDiff(A_,B_), ch=d.filter(x=>x[0]!==' ');
      html+=`<h3 class="mono" style="margin:10px 0 4px">${fname(diffSel.a,n)} → ${fname(diffSel.b,n)} <span class="muted small">${ch.length? ch.length+' changed lines':'identical'}</span></h3>`;
      if (ch.length){ const keep=new Set(); d.forEach((x,i)=>{ if (x[0]!==' ') for (let k=Math.max(0,i-2);k<=Math.min(d.length-1,i+2);k++) keep.add(k); }); let last=-2;
        html+='<div class="mono small" style="white-space:pre;overflow:auto;max-height:260px;background:var(--lane);border-radius:6px;padding:6px">'+d.map((x,i)=>{ if (!keep.has(i)) return ''; const gap= i!==last+1? '<div class="muted">  ⋯</div>' : ''; last=i; return gap+`<div style="color:${x[0]==='+'?'var(--accent)':x[0]==='-'?'var(--bad)':'var(--ink2)'}">${x[0]} ${String(x[2]).padStart(4)}  ${esc(x[1])}</div>`; }).join('')+'</div>'; } });
    m.querySelector('#df').innerHTML=html; m.querySelector('#da').onchange=e=>{ diffSel.a=e.target.value; drawDiff(); }; m.querySelector('#db').onchange=e=>{ diffSel.b=e.target.value; drawDiff(); }; };
  drawDiff();
  const draw=()=>{ const t=SIM.t, s=S(), I=s.I, q=snapAt(t), rp=replay(t,14), r=regAt(t);
    // main loop strip
    let k=-1; const cur=rp&&rp.cur; if (q && q.n+1<s.passes.length){ const off=s.cyc(t)-s.passes[q.n]; for (let i=0;i<s.K;i++){ if (s.stamps[q.n*s.K+i]<=off) k=i; } }
    const W_=Math.ceil(s.K/2);
    m.querySelector('#ml').innerHTML=`<svg viewBox="0 0 ${W_*121+10} 120" style="width:100%">${I.calls.map((cl,i)=>{ const x=6+(i%W_)*121, y=6+Math.floor(i/W_)*56, on=i===k, cy=q&&q.n+1<s.passes.length? ((i+1<s.K? s.stamps[q.n*s.K+i+1] : s.passes[q.n+1]-s.passes[q.n]) - s.stamps[q.n*s.K+i]) : 0; return `<rect x="${x}" y="${y}" width="115" height="48" rx="6" fill="${on?'var(--accent)':'var(--panel2)'}" stroke="var(--line)"/><text x="${x+7}" y="${y+20}" font-size="${cl.name.length>14?9.5:11}" font-family="var(--mono)" fill="${on?'#fff':'var(--ink)'}">call ${cl.name}</text><text x="${x+7}" y="${y+38}" font-size="10" fill="${on?'#eef':'var(--ink2)'}">${cy} cycles · 0x${cl.a.toString(16).padStart(3,'0')}</text>`; }).join('')}</svg>
      <p class="small muted">${q? `Pass ${q.n} · ${s.passes[q.n+1]? s.passes[q.n+1]-s.passes[q.n] : '?'} cycles. Then <span class="mono">goto main</span>.` : 'The PIC is in INIT'+(D.cfg.fw==='v102'?' or the v102 delay loop':'')+'.'}</p>`;
    // source
    if (cur){ const sl=srcLine(I, cur.pc); const fi=I.refs[cur.pc][0], f=I.files[fi], ln=I.refs[cur.pc][1]; const lines=f[1];
      // address of each source line in this file (for the gutter)
      const addrOf={}; for (let a=0;a<I.n;a++){ const rr=I.refs[a]; if (rr && rr[0]===fi && rr.length===2 && !(rr[1] in addrOf)) addrOf[rr[1]]=a; }
      const a0=Math.max(1,ln-12), a1=Math.min(lines.length,ln+12); let h=`<div class="muted">${f[0]} · line ${ln}${sl.via?` · inside macro, called from ${sl.via.file}:${sl.via.line}`:''} · PC 0x${cur.pc.toString(16).padStart(3,'0')} · word 0x${I.code[cur.pc].toString(16).padStart(4,'0')} → ${dis(I.code[cur.pc],I)}</div>`;
      for (let L=a0; L<=a1; L++){ const on=L===ln, ad=addrOf[L]; h+=`<div style="${on?'background:var(--accent);color:#fff;border-radius:3px':''}">${ad!==undefined?ad.toString(16).padStart(3,'0'):'   '} ${String(L).padStart(4)}  ${esc(FW.S[lines[L-1]]||'')}</div>`; }
      m.querySelector('#src').innerHTML=h; }
    else m.querySelector('#src').innerHTML='<span class="muted">No replay data at this time.</span>';
    m.querySelector('#ring').innerHTML = rp? `<table class="kv"><tr><th>cycle</th><th>PC</th><th>instruction</th><th>W</th><th>Z C</th></tr>${rp.ring.map((e,i)=>`<tr style="${i===rp.ring.length-1?'font-weight:700;color:var(--accent)':''}"><td>${SIM.fmtT(s.tOf(e.c))}</td><td>${e.pc.toString(16).padStart(3,'0')}</td><td>${I.labAt[e.pc]?'<span class="muted">'+I.labAt[e.pc]+':</span> ':''}${dis(I.code[e.pc],I)}</td><td>${hx(e.W)}</td><td>${(e.st>>2)&1} ${e.st&1}</td></tr>`).join('')}</table>` : '';
    // RAM
    m.querySelector('#ram').innerHTML = r? `<table class="kv small"><tr><th>addr</th><th>symbol</th><th>value</th></tr>${Object.keys(I.ram).sort((x,y)=>I.ram[x]-I.ram[y]).map(k2=>{ const a=I.ram[k2]; const nm=I.ramRev[a]; return `<tr><td class="mono">0x${a.toString(16)}</td><td class="mono">${nm}</td><td class="mono">${bn(r[k2])} <span class="muted">0x${hx(r[k2])}</span></td></tr>`; }).join('')}<tr><td class="mono">PORTB</td><td class="mono">LEDs</td><td class="mono">${bn(r.portb)}</td></tr></table>` : '<p class="muted">INIT</p>';
    const f=frameAt(t), a5=r? (r.sources1>>5)&1 : 0, sdi=r && (r.sources1&128);
    m.querySelector('#sm').innerHTML=`<svg viewBox="0 0 420 160" style="width:100%"><defs><marker id="dmsd" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0L10,5L0,10z" fill="var(--ink2)"/></marker></defs>
      ${[[20,'XTM41 (10)',0],[240,'DEMUX (11)',1]].map(([x,l,v])=>`<rect x="${x}" y="50" width="160" height="56" rx="28" fill="${sdi&&a5===v?'var(--accent)':'var(--panel2)'}" stroke="var(--line)"/><text x="${x+80}" y="83" text-anchor="middle" font-size="13" fill="${sdi&&a5===v?'#fff':'var(--ink)'}">${l}</text>`).join('')}
      <path d="M180 62 Q210 28 240 62" fill="none" stroke="var(--ink2)" marker-end="url(#dmsd)"/><path d="M240 94 Q210 128 180 94" fill="none" stroke="var(--ink2)" marker-end="url(#dmsd)"/><text x="210" y="24" text-anchor="middle" font-size="10" fill="var(--ink2)">reply → sdi_control: xorwf sources1 (bit 5)</text><text x="210" y="148" text-anchor="middle" font-size="10" fill="var(--ink2)">reply, or time-out → re_transmit clears bit 5</text></svg>
      <p class="small">${sdi? `SDI mode — next frame to the ${a5?'DEMUX':'XTM41'}. While bit 5 is set, <span class="mono">sdimode</span> returns at once: LEDs and flash counters freeze for that half of the cycle.` : 'Not in SDI mode: every frame goes to the XTM41 with the mode\'s own address.'}${f?` Last frame 0x${hx(f.tx0)} → ${ADDR[f.addr]}.`:''}</p>`;
    // EEPROM
    { const M=rp? rp.M : null; const mem=M? M.ee.mem : null; m.querySelector('#ee').innerHTML = mem? `<table class="kv small"><tr><th>word</th><th>value</th><th>meaning</th></tr>${[[0,'sourcea · alvl1'],[1,'sourced · dlvl1'],[2,'sources2 · slvl1'],[3,'sources1 · sources1'],[10,'0xAAAA = “saved before”']].map(([a,l])=>`<tr><td class="mono">${a}</td><td class="mono">0x${mem[a].toString(16).toUpperCase().padStart(4,'0')}</td><td>${l}</td></tr>`).join('')}</table><p class="small">${M.ee.ewen?'Write-enabled (EWEN latched — eewrite never sends EWDS). ':''}${M.cyc<M.ee.busyUntil?'<b>Busy writing.</b> ':''}Mode: ${M.ee.mode}${M.ee.status?' · CS high, DO shows ready/busy':''}.</p>` : ''; }
    const fw=D.cfg.fw; m.querySelector('#ld').innerHTML=flowSVG([{t:'sources1,5 ?',s:['frame for DEMUX','→ return (frozen)']},{t:'flag0,2 ?',s:['closure → clear PORTB','light SDI']},{t:'disctl,1 ?',s:['no carrier','→ sdidis3 (flash SDI)']},{t:'disctl,0 ?',s:['group unlocked','→ sdidis2 (flash GR)']},{t:'no_sdi',s:['bcf portb,2',fw==='v102'?'v102: falls into no_audio':'v100/101: return']},{t:'source_led',s:['SDI on','GRn (+SWAP) from sources2']}], r? (!(r.sources1&128)? -1 : (r.sources1&32)?0:(r.disctl&2)?2:(r.disctl&1)?3:5) : -1); };
  SIM.on('time',draw); }

/* ---------------- findings ---------------- */
function viewNotes(m){ window.__dmsActive=false; const s=S(), ps=s.passStat;
  m.innerHTML=card('How this folder relates to the DMS1',`<p><b>Same product, earlier layer.</b> <span class="mono">#DMS #SERIES/XXX - DMS - #OBSOLETE #Archive</span> holds the DMS-1 as designed 2001–2011: the front-panel firmware (the only code of the product), the 2001 DEMUX-1 rear silk, the 2011 front and DEMUX-3 rear silks, both functional drawings and photos of the DEMUX-3 unit (April 2011). <span class="mono">XXX - DMS1 - #Master #OBSOLETE</span> (dms1.js) is the later master: the 2014 DEMUX-4 version, its plate, the test reports and the 2016 drafting silks. The XTM41 code that answers this panel lives in <span class="mono">XTM4 - #MASTER</span> (xtm4.js); the DEMUX code in the DEMUX folders. The panels here use the 2011 artwork on the same coordinate frame as dms1.js, so buttons, meter and connectors sit in the same places in both plugins.</p>`)
  +card('Findings — from running the code',`<ol>
   <li><b>The archive's hex backup is V102, and the source rebuilds it exactly.</b> Assembling <span class="mono">Dms1v102/dms1v101.asm</span> gives 1094 words that match <span class="mono">DMS1V101.BKX</span> (MPLAB's backup of the previous HEX, 25 Feb 2011 08:55) with no differences. So the deleted factory HEX can be recreated from this folder. The V102 project still builds <span class="mono">DMS1V101.HEX</span> from <span class="mono">dms1v101.asm</span>, a source of version confusion.</li>
   <li><b>Root cause of the start-up SDI flashing: <span class="mono">disctl</span> is never cleared.</b> INIT clears most variables but not <span class="mono">disctl</span>, <span class="mono">lockflash4</span> or <span class="mono">flag0</span> bits 0–1. With a restored SDI mode, a power-on RAM value with <span class="mono">disctl,1</span> = 1 sends <span class="mono">sdimode</span> into <span class="mono">sdidis3</span>: the SDI LED flashes from the first pass until the first DEMUX reply (≈1 s with v101). It depends on the RAM pattern, which matches the report's “sometime when startup”. The v102 fix (a 0.64 s delay) only shortens this window. <span class="mono">clrf disctl</span> in INIT would remove it ${inf}.</li>
   <li><b>v102 also changes the XTM41 side.</b> On the same date, 18 Feb 2011, XTM41 “VERSION 2.03 … ONLY for DMS-1 Units / The issue with SDI LED flashing at startup is fixed” was released. That build replies <span class="mono">cs8420_16 &amp; 1</span> instead of the XTM4 pattern. In SDI mode the front panel ignores XTM41 replies (<span class="mono">processuart</span> returns unless <span class="mono">sources1,5</span>), so that part of the fix cannot affect the LED.</li>
   <li><b>The v102 dates do not agree.</b> The header says “FEBRUERY 18, 2011”. The changed files are older: <span class="mono">init42~1.asm</span> (delay loop) is dated 29 Jul 2010 and <span class="mono">sdi42.asm</span> (no_sdi) 4 Aug 2010. The build (XRF) is 25 Feb 2011, and the test report approving V102 is dated 15 Feb 2011.</li>
   <li><b>Why v101 added <span class="mono">communication_control</span>: a bus collision, reproduced.</b> v100 transmits as soon as <span class="mono">txflags,0</span> is set and no reply is pending. If a button's closure lands while the PIC is waiting for a reply, the next frame starts in the same pass the reply arrives. The XTM41 only releases the bus in its next <span class="mono">txuart</span>, ≈1.25 ms later (<span class="mono">txuart1</span>: “turn transmitter off”). The address byte collides, the XTM41 gets a framing error (<span class="mono">rxerror1</span>) and the PIC waits for <span class="mono">loss_of_com</span>. v101's 150-pass hold (≈${(150*ps.med*TCY*1000).toFixed(0)} ms) removes it. The tutorial reproduces it on demand.</li>
   <li><b>The real pass is ${ps.med} cycles (${(ps.med*TCY*1e6).toFixed(0)} µs), not 150.</b> Measured over this second: min ${ps.min}, median ${ps.med}, max ${ps.max} cycles (eewrite passes excepted). dms1.js assumed 150 cycles, so its debounce, poll and flash times are about ${((150/ps.med-1)*100).toFixed(0)} % too long.</li>
   <li><b>eewrite stops the unit for ≈20 ms.</b> EWEN, a 6-turn wait, then five WRITEs, each followed by a busy-wait on DO (<span class="mono">eerwait</span>). No <span class="mono">clrwdt</span> runs, and no button, LED or UART work happens in that time. A reply arriving then waits in the 2-byte FIFO. The EEPROM is never sent EWDS and CS is left high.</li>
   <li><b>The “first time” check reads one byte twice.</b> INIT compares <span class="mono">setup1</span> with 0xAA twice and never checks <span class="mono">setup2</span>. Word 3 stores <span class="mono">sources1</span> in both halves, and INIT restores <span class="mono">sources1</span> twice.</li>
   <li><b>Spurious save after power-on.</b> <span class="mono">flag0,1</span> (“wait for release”) is not cleared. If the RAM powers up with it set, <span class="mono">wait</span> runs 128 passes, then sets <span class="mono">press_flag,2</span>, and ≈${(46336*ps.med*TCY).toFixed(1)} s later the EEPROM is rewritten with nothing changed: one extra write cycle at some power-ons ${inf}.</li>
   <li><b>GR4 shares RC2 with the EEPROM data line.</b> <span class="mono">eewrite</span> sets TRISC = 0x83 (RC2 output, “change portc,0,1 to outputs”) and <span class="mono">nomatch</span> 0x87 (RC2 input). The comments name the wrong pins, since RC0/RC1 stay inputs (SWAP, EE DO) in both. While RC2 is an output, a GR4 press is not seen, and the press shorts the driven line ${inf}.</li>
   <li><b>LEDs blink for one cycle every pass in AUDIO and AES.</b> <span class="mono">analogmode</span> (after a closure) and <span class="mono">aes_led</span> (every pass while locked) do <span class="mono">clrf PORTB</span> then <span class="mono">bsf PORTB,n</span>. The LED is dark for 1 of ≈${ps.med} cycles. This is invisible, but it shows on the raw PORTB trace.</li>
   <li><b>DEMUX-3 v400 never reports missing audio and changes group slowly.</b> In <span class="mono">process_uart</span>, all the lines that would set bit 0 or bits 2–5 are commented out, so <span class="mono">sdidis2</span> (group LED flashing) can only ever run with the DEMUX-1. A new group takes effect on the 4th DEMUX frame in a row (<span class="mono">GROUP_CONSTANT</span> 3), about one second at the poll rate. Note that <span class="mono">v204</span> has <span class="mono">GROUP_CONSTANT 10 //Ali-Add</span> and v400 is back to 3, the reverse of the DEMUX3 README's “3 → 10”.</li>
   <li><b>SDI mode freezes the LEDs half the time.</b> <span class="mono">sdimode</span> starts with <span class="mono">btfsc sources1,5 / return</span>, so while the last frame went to the DEMUX the LED and flash code stands still. With no DEMUX fitted, every DEMUX frame times out (${(26*256*ps.med*TCY).toFixed(2)} s with v101/v102), so the panel is frozen most of the time. Try DEMUX → none.</li>
   <li><b>The level byte never changes.</b> <span class="mono">alvl1</span> = 64 (“+4”) and <span class="mono">dlvl1</span> = <span class="mono">slvl1</span> = 40 (“−20”) are set in INIT and never changed. The DMS-1 has no level keys, but the XTM42 protocol is sent in full.</li>
   <li><b>XTM42 leftovers.</b> <span class="mono">init42~1.asm</span> keeps the 8-character display macros (PORTD), the CHARA–CHAR9 table, a “phase meter” on PORTE and <span class="mono">auto1/auto2</span>; 19 of the RAM variables (dis0–dis7, an_mode, dig_mode, alvl2, dlvl2, slvl2, msblvl, lsblvl, DISDEL, SOURCEANL, multisend0/1) are never referenced and a dozen more are only cleared in INIT. The 28-pin PIC16C73B/F73 has no PORTD or PORTE, and the macros are never expanded, so it still assembles. The v100 project file still lists <span class="mono">XTM42V~1.ASM</span> / <span class="mono">XTM43V~1.ASM</span> targets with P16C74B headers, and every version folder has an empty <span class="mono">XTM43V~1.ERR</span>.</li>
   <li><b>Header mismatch accepted.</b> <span class="mono">DMS1V101.ERR</span> (v101 and v102) is “Message[301] … P16F73.INC … Processor-header file mismatch”: the processor selected in <span class="mono">dms2.pjt</span> (<span class="mono">Processor=0x663a</span>) is not the one the source includes. The code only uses registers at the same addresses on the PIC16C73B and PIC16F73, so the image is unaffected ${inf}.</li>
   <li><b>Watchdog would survive v102's delay.</b> No <span class="mono">__CONFIG</span> is in the source. If the WDT is enabled, OPTION_REG keeps its reset prescaler (only bit 7 is cleared), so the WDT period is ≥ 0.9 s, longer than the 0.64 s delay loop, which has no <span class="mono">clrwdt</span> ${inf}.</li>
   <li><b>Artwork history in the folder.</b> The rear silk changed between DEMUX-1 (2001: SDI OUTPUT left of INPUT, no AES outputs) and DEMUX-3 (2011: INPUT, OUTPUT, 1, 2, “DISEMBEDDED AES OUTPUTS”). <span class="mono">DMSREAR.CDR</span> and <span class="mono">DMSREAR_CURVE.cdr</span> are the same 2001 rear (text vs curves). The DMS-1 FRONT.dwg title text still carries POD10-REAR / ABB-M1 and “POWDER COAT BEIGE” from the drawing it was copied from.</li>
   <li><b>Meter scale drift.</b> The silk is −34 … +12 with “3 6 9 12”. The 2003 manual cover <span class="mono">DMS1manu.cdr</span> prints “3 8 9 12”, and both functional drawings say −27 … +12.</li></ol>`)
  +card('Assumptions in this simulation',`<ul class="small"><li>Everything the front PIC does is its own code. Pass lengths, debounce, poll and time-out timing are measured, not assumed.</li>
    <li>Slaves are behavioural models built from their code: the XTM41 reads one byte per ≈1.25 ms pass and replies at the end of that pass, keeping its driver on until the next pass (pass length and phase from xtm4.js, ${inf}). DEMUX-1 replies after 75 passes of ≈150 cycles (${inf}). DEMUX-3 replies ≈2 ms after the frame and releases the bus ≈2 ms later (${inf}).</li>
    <li>Start-up times: XTM41 0.25 s, DEMUX-1 0.35 s, DEMUX-3 0.6 s (${inf}, as in dms1.js). 93LC66B write time 4 ms (${inf}; data sheet ≤ 6 ms). RS-485 receiver disabled while the PIC drives (${inf}).</li>
    <li>RAM at power-on: the PIC data sheet gives GPRs as unknown. The “patterns” are deterministic pseudo-random fills. Contact bounce is not modelled: a press is a clean 80 ms low.</li>
    <li>Meter: 0 dB = +4 dBu analog or −20 dBFS digital (INIT: alvl1 64 “+4”, dlvl1 40 “−20”), fast attack, 13 dB/s fall (${inf}).</li></ul>`)
  +card('Sources',`<ul class="small mono"><li>#DMS #SERIES/XXX - DMS - #OBSOLETE #Archive/PIC VERSIONS/Dms1v100 · Dms1v101 · Dms1v102 (asm, BKX, XRF, ERR, pjt)</li><li>… DMSFRTS.cdr · DMSRear-Demux3.cdr · DMSREAR_CURVE.cdr · DMS1-Functional.cdr · DMS1-obsolete.cdr · DMS1manu*.cdr · DMS1-*Demux3-1.jpg · DMS-1 FRONT.dwg</li><li>XTM4 - #MASTER/…/xtm41/PIC VERSIONS/41v203, 41v204/ONLY_DMS1/41v202.asm</li><li>#DEMUX #SERIES/XXX - DEMUX1 …/v106b/demux-1v106.asm, demux-1.asm · XXX - DEMUX3 …/atmel/v400/demux3_v400.c, v204/demux204.c</li><li>Assembler: siumulation-plugins/tools/dms-mpasm.py</li></ul>`); }

